class Fresh(IterableDataset):
    def __iter__(self):
        for _ in range(3):
            x=torch.randn(2);yield x,2*x[0]-3.4*x[1]+4.2

class Fixed(IterableDataset):
    def __iter__(self):
        g=torch.Generator().manual_seed(42)
        for _ in range(3):
            x=torch.randn(2,generator=g);yield x,2*x[0]-3.4*x[1]+4.2
